python3 - <<'EOF'
p='src/pickList.ts'
s=open(p).read()
i=s.index('export function buildPickList')
s=s[:i]+'''interface OrderItem {
  sku: string;
  qty: number;
}

interface Order {
  id: string;
  priority: boolean;
  items: OrderItem[];
}

const ORDER_LINE = /^ORDER +([A-Za-z0-9-]+)( +!)?$/;
const ITEM_LINE = /^([A-Z0-9-]+) +x([1-9][0-9]*)$/;

function parseOrders(ordersText: string): Order[] {
  const orders: Order[] = [];
  const seenIds = new Set<string>();
  // Empty orders are only detected once the next ORDER line (or the end) is
  // reached, so collect the earliest problem instead of throwing right away.
  let firstError: OrderFormatError | null = null;
  const report = (line: number, description: string) => {
    if (firstError === null || line < firstError.line) {
      firstError = new OrderFormatError(line, description);
    }
  };

  let current: { order: Order; line: number } | null = null;
  const closeCurrent = () => {
    if (current !== null && current.order.items.length === 0) {
      report(current.line, `order ${current.order.id} has no items`);
    }
  };

  const lines = ordersText.split("\\n");
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1;
    const line = lines[i].trim();
    if (line === "" || line.startsWith("#")) continue;

    const orderMatch = ORDER_LINE.exec(line);
    if (orderMatch) {
      closeCurrent();
      const id = orderMatch[1];
      const order: Order = { id, priority: orderMatch[2] !== undefined, items: [] };
      if (seenIds.has(id)) {
        report(lineNo, `duplicate order id ${id}`);
      } else {
        seenIds.add(id);
        orders.push(order);
      }
      current = { order, line: lineNo };
      continue;
    }

    const itemMatch = ITEM_LINE.exec(line);
    if (itemMatch) {
      if (current === null) {
        report(lineNo, "item line before the first ORDER line");
        continue;
      }
      const sku = itemMatch[1];
      const qty = Number(itemMatch[2]);
      const existing = current.order.items.find((item) => item.sku === sku);
      if (existing) existing.qty += qty;
      else current.order.items.push({ sku, qty });
      continue;
    }

    report(lineNo, `unrecognized line "${line}"`);
  }
  closeCurrent();

  if (firstError !== null) throw firstError;
  return orders;
}

interface Lot {
  bin: string;
  remaining: number;
  expires: string | null;
  index: number;
}

function compareLots(a: Lot, b: Lot): number {
  if (a.expires !== b.expires) {
    if (a.expires === null) return 1;
    if (b.expires === null) return -1;
    return a.expires < b.expires ? -1 : 1;
  }
  if (a.bin !== b.bin) return a.bin < b.bin ? -1 : 1;
  return a.index - b.index;
}

function parseBin(bin: string): { aisle: string; rack: number; level: number } {
  const [aisle = "", rack = "", level = ""] = bin.split("-");
  return { aisle, rack: Number(rack), level: Number(level) };
}

function walkOrder(picks: Pick[]): Pick[] {
  const entries = picks.map((pick, index) => ({ pick, index, ...parseBin(pick.bin) }));
  const aisles = [...new Set(entries.map((e) => e.aisle))].sort();
  const aisleRank = new Map(aisles.map((aisle, i) => [aisle, i]));
  entries.sort((a, b) => {
    const rankA = aisleRank.get(a.aisle)!;
    const rankB = aisleRank.get(b.aisle)!;
    if (rankA !== rankB) return rankA - rankB;
    if (a.rack !== b.rack) return rankA % 2 === 0 ? a.rack - b.rack : b.rack - a.rack;
    if (a.level !== b.level) return a.level - b.level;
    return a.index - b.index;
  });
  return entries.map((e) => e.pick);
}

export function buildPickList(ordersText: string, stock: StockLot[]): PickList {
  const orders = parseOrders(ordersText);

  const lotsBySku = new Map<string, Lot[]>();
  stock.forEach((lot, index) => {
    let lots = lotsBySku.get(lot.sku);
    if (!lots) lotsBySku.set(lot.sku, (lots = []));
    lots.push({ bin: lot.bin, remaining: lot.qty, expires: lot.expires, index });
  });
  for (const lots of lotsBySku.values()) lots.sort(compareLots);

  const served = [...orders.filter((o) => o.priority), ...orders.filter((o) => !o.priority)];
  const picks: Pick[] = [];
  const shortages: Shortage[] = [];
  for (const order of served) {
    for (const item of order.items) {
      let needed = item.qty;
      for (const lot of lotsBySku.get(item.sku) ?? []) {
        if (needed === 0) break;
        if (lot.remaining <= 0) continue;
        const taken = Math.min(needed, lot.remaining);
        lot.remaining -= taken;
        needed -= taken;
        picks.push({ bin: lot.bin, sku: item.sku, qty: taken, orderId: order.id });
      }
      if (needed > 0) shortages.push({ orderId: order.id, sku: item.sku, missing: needed });
    }
  }

  return { picks: walkOrder(picks), shortages };
}
'''
open(p,'w').write(s)
EOF

cat >> src/pickList.test.ts <<'EOF'

import { buildPickList, type StockLot } from "./pickList";

function formatError(text: string): OrderFormatError {
  try {
    buildPickList(text, []);
  } catch (error) {
    if (error instanceof OrderFormatError) return error;
    throw error;
  }
  throw new Error("expected an OrderFormatError");
}

test("example batch: priority first, earliest expiry first, serpentine walk", () => {
  const text = [
    "# export 2026-10-12 06:00",
    "ORDER 1001",
    "  OLIVE-500 x3",
    "  PASTA-1KG x1",
    "ORDER 1002 !",
    "  OLIVE-500 x2",
  ].join("\n");
  const stock: StockLot[] = [
    { bin: "A-01-1", sku: "OLIVE-500", qty: 2, expires: null },
    { bin: "B-02-1", sku: "OLIVE-500", qty: 2, expires: "2026-12-01" },
    { bin: "B-05-3", sku: "OLIVE-500", qty: 1, expires: "2026-11-01" },
    { bin: "C-04-1", sku: "PASTA-1KG", qty: 5, expires: "2027-01-01" },
  ];
  const snapshot = structuredClone(stock);
  const result = buildPickList(text, stock);
  expect(stock).toEqual(snapshot);
  expect(result.shortages).toEqual([]);
  expect(result.picks).toEqual([
    { bin: "A-01-1", sku: "OLIVE-500", qty: 2, orderId: "1001" },
    { bin: "B-05-3", sku: "OLIVE-500", qty: 1, orderId: "1002" },
    { bin: "B-02-1", sku: "OLIVE-500", qty: 1, orderId: "1002" },
    { bin: "B-02-1", sku: "OLIVE-500", qty: 1, orderId: "1001" },
    { bin: "C-04-1", sku: "PASTA-1KG", qty: 1, orderId: "1001" },
  ]);
});

test("shortages, merged duplicates and bin tie-break", () => {
  const text = "ORDER A-1\nX x2\nY x4\nX x3\nORDER b2\nY x1";
  const stock: StockLot[] = [
    { bin: "A-02-1", sku: "X", qty: 3, expires: "2026-11-01" },
    { bin: "A-01-1", sku: "X", qty: 1, expires: "2026-11-01" },
    { bin: "A-03-1", sku: "Y", qty: 0, expires: null },
  ];
  const result = buildPickList(text, stock);
  expect(result.picks).toEqual([
    { bin: "A-01-1", sku: "X", qty: 1, orderId: "A-1" },
    { bin: "A-02-1", sku: "X", qty: 3, orderId: "A-1" },
  ]);
  expect(result.shortages).toEqual([
    { orderId: "A-1", sku: "X", missing: 1 },
    { orderId: "A-1", sku: "Y", missing: 4 },
    { orderId: "b2", sku: "Y", missing: 1 },
  ]);
});

test("serpentine counts only visited aisles", () => {
  const stock: StockLot[] = ["A-01-2", "A-02-1", "C-01-1", "C-03-2", "C-03-1", "D-01-1", "D-05-1"].map(
    (bin) => ({ bin, sku: bin.replace(/-/g, ""), qty: 1, expires: null }),
  );
  const text = "ORDER 1\n" + stock.map((l) => `${l.sku} x1`).reverse().join("\n");
  const bins = buildPickList(text, stock).picks.map((p) => p.bin);
  expect(bins).toEqual(["A-01-2", "A-02-1", "C-03-1", "C-03-2", "C-01-1", "D-01-1", "D-05-1"]);
});

test("format errors", () => {
  expect(formatError("\nX x1\nORDER 1\nX x1").line).toBe(2);
  expect(formatError("ORDER 1\nX x1\nORDER 1\nX x1").line).toBe(3);
  expect(formatError("ORDER 1\nORDER 2\nX x1").line).toBe(1);
  expect(formatError("ORDER 1\nX x1\nORDER 2\n# c\n").line).toBe(3);
  expect(formatError("ORDER 1\nX x0").line).toBe(2);
  expect(formatError("ORDER 1\nX x03").line).toBe(2);
  expect(formatError("ORDER 1\nx x1").line).toBe(2);
  expect(formatError("ORDER 1\nX 1").line).toBe(2);
  expect(formatError("ORDER 1!\nX x1").line).toBe(1);
  expect(formatError("ORDER 1\nbad\nX x1\nORDER 1\n").line).toBe(2);
  expect(formatError("ORDER 1\nbad\nORDER 2\nX x1").line).toBe(1);
  expect(buildPickList("ORDER 1   !\nX   x1", []).shortages).toEqual([{ orderId: "1", sku: "X", missing: 1 }]);
});
EOF
